<?php
declare(strict_types=1);
require_once __DIR__."/maintenance_helper.php";
require_once __DIR__."/equipment_unit_helper.php";
require_once __DIR__."/notification_helper.php";

function gsoCreateReturnRepairWorkOrder(PDO $pdo,int $returnItemId,int $adminId,int $assigneeId,int $durationDays,string $remarks=""):array{
 try{$pdo->beginTransaction();
  $a=$pdo->prepare("SELECT role FROM users WHERE user_id=? AND role='Admin' AND account_status='Approved' AND email_verified=1 FOR UPDATE");$a->execute([$adminId]);if($a->fetchColumn()!=="Admin")throw new DomainException("Only the GSO Head may create a damaged-return repair work order.");
  $s=$pdo->prepare("SELECT i.return_item_id,i.return_id,i.unit_id,i.returned_quantity,i.lost_quantity,i.inspection_condition,i.stock_applied,ri.resource_id,r.tracking_mode,r.resource_type FROM return_submission_items i JOIN request_items ri ON ri.request_item_id=i.request_item_id JOIN resources r ON r.resource_id=ri.resource_id WHERE i.return_item_id=? FOR UPDATE");$s->execute([$returnItemId]);$d=$s->fetch(PDO::FETCH_ASSOC);
  if(!$d||!in_array((string)$d['inspection_condition'],['Damaged','Needs Repair','Missing Parts'],true)||(int)$d['stock_applied']!==1||(int)$d['lost_quantity']!==0||(int)$d['returned_quantity']<1)throw new DomainException("This return detail is not eligible for repair.");
  $serialized=(string)$d['tracking_mode']==='Serialized';$unitId=(int)($d['unit_id']??0);$qty=$serialized?1:max(1,(int)$d['returned_quantity']);if($serialized&&$unitId<=0)throw new DomainException("The serialized return detail has no physical unit.");
  if($d['resource_type']==='Facility'){$qty=0;}elseif($serialized){$unit=$pdo->prepare("SELECT 1 FROM equipment_units WHERE unit_id=? AND resource_id=? AND status='Under Repair' AND condition_status IN('Damaged','Missing Parts','Needs Repair') FOR UPDATE");$unit->execute([$unitId,(int)$d['resource_id']]);if(!$unit->fetchColumn())throw new DomainException("The linked physical unit is not awaiting repair.");}else{$resource=$pdo->prepare("SELECT under_repair_stock FROM resources WHERE resource_id=? FOR UPDATE");$resource->execute([(int)$d['resource_id']]);if((int)$resource->fetchColumn()<$qty)throw new DomainException("The aggregate repair quantity does not match held inventory.");}
  $dup=$pdo->prepare("SELECT 1 FROM maintenance_schedules WHERE source_return_item_id=? AND (status IN ('Scheduled','In Progress') OR restored_at IS NOT NULL) FOR UPDATE");$dup->execute([$returnItemId]);if($dup->fetchColumn())throw new DomainException("An active repair work order already exists for this return detail.");
  if($assigneeId>0){$u=$pdo->prepare("SELECT 1 FROM users WHERE user_id=? AND role IN ('Admin','GSO Staff') AND account_status='Approved' AND email_verified=1");$u->execute([$assigneeId]);if(!$u->fetchColumn())throw new DomainException("Select an eligible GSO assignee.");}
  $durationDays=max(1,min(365,$durationDays));$start=date('Y-m-d');$end=calculateMaintenanceEndDate($start,$durationDays);
  $i=$pdo->prepare("INSERT INTO maintenance_schedules(maintenance_type,resource_id,quantity,source_return_id,source_return_item_id,equipment_unit_id,assigned_to,start_date,end_date,duration_days,reason,remarks,status,created_by,updated_by,updated_at) VALUES('Corrective',?,?,?,?,?,?,?,?,?,?,?,'In Progress',?,?,NOW())");
  $i->execute([(int)$d['resource_id'],$qty,(int)$d['return_id'],$returnItemId,$unitId?:null,$assigneeId?:null,$start,$end,$durationDays,'Repair from inspected return detail #'.$returnItemId,$remarks?:null,$adminId,$adminId]);$id=(int)$pdo->lastInsertId();if($assigneeId>0)createNotification($pdo,$assigneeId,'work_order_assigned','Repair Work Order Assigned',"MTN-{$id} was assigned to you.",'maintenance.php');$pdo->commit();return ['ok'=>true,'message'=>"Work order MTN-{$id} created.",'maintenance_id'=>$id];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}
}

function gsoAssignRepairWorkOrder(PDO $pdo,int $maintenanceId,int $actorId,int $assigneeId):array{
 try{$pdo->beginTransaction();
  $actor=$pdo->prepare("SELECT role FROM users WHERE user_id=? AND role IN ('Admin','GSO Staff') AND account_status='Approved' AND email_verified=1 FOR UPDATE");$actor->execute([$actorId]);if(!is_string($actor->fetchColumn()))throw new DomainException("Account is not authorized for work orders.");
  $assignee=$pdo->prepare("SELECT 1 FROM users WHERE user_id=? AND role IN ('Admin','GSO Staff') AND account_status='Approved' AND email_verified=1 FOR UPDATE");$assignee->execute([$assigneeId]);if(!$assignee->fetchColumn())throw new DomainException("Select an eligible GSO assignee.");
  gsoValidateRepairSource($pdo,$maintenanceId);
  $work=$pdo->prepare("SELECT maintenance_id FROM maintenance_schedules WHERE maintenance_id=? AND status IN ('Scheduled','In Progress') FOR UPDATE");$work->execute([$maintenanceId]);if(!$work->fetchColumn())throw new DomainException("Only an active work order can be assigned.");
  $update=$pdo->prepare("UPDATE maintenance_schedules SET assigned_to=?,updated_by=?,updated_at=NOW() WHERE maintenance_id=? AND status IN ('Scheduled','In Progress')");$update->execute([$assigneeId,$actorId,$maintenanceId]);
  createNotification($pdo,$assigneeId,'work_order_assigned','Repair Work Order Assigned',"MTN-{$maintenanceId} was assigned to you.",'maintenance.php');
  $pdo->commit();return ['ok'=>true,'message'=>'Work order assigned.'];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}
}

function gsoCompleteRepairWorkOrder(PDO $pdo,int $maintenanceId,int $actorId,string $notes):array{
 $type=$pdo->prepare('SELECT maintenance_type FROM maintenance_schedules WHERE maintenance_id=?');$type->execute([$maintenanceId]);if($type->fetchColumn()==='Preventive'){require_once __DIR__.'/preventive_maintenance_helper.php';return gsoPreventiveJobAction($pdo,$maintenanceId,$actorId,'complete',$notes);}
 try{$pdo->beginTransaction();$u=$pdo->prepare("SELECT role FROM users WHERE user_id=? AND role IN ('Admin','GSO Staff') AND account_status='Approved' AND email_verified=1 FOR UPDATE");$u->execute([$actorId]);$role=$u->fetchColumn();if(!is_string($role))throw new DomainException("Account is not authorized for work orders.");
  $s=$pdo->prepare("SELECT * FROM maintenance_schedules WHERE maintenance_id=? FOR UPDATE");$s->execute([$maintenanceId]);$w=$s->fetch(PDO::FETCH_ASSOC);if(!$w)throw new DomainException("Work order not found.");if((string)$w['status']==='Completed'||!empty($w['restored_at']))throw new DomainException("This work order was already completed.");if(!in_array((string)$w['status'],['Scheduled','In Progress'],true))throw new DomainException("Only active work orders can be completed.");if($role!=='Admin'&&(int)($w['assigned_to']??0)!==$actorId)throw new DomainException("Only the assigned GSO personnel may complete this work order.");
  gsoValidateRepairSource($pdo,$maintenanceId);
  $restored=0;$unitId=(int)($w['equipment_unit_id']??0);
  if($unitId>0){$unit=$pdo->prepare("SELECT resource_id,status,condition_status FROM equipment_units WHERE unit_id=? FOR UPDATE");$unit->execute([$unitId]);$row=$unit->fetch(PDO::FETCH_ASSOC);if(!$row||(int)$row['resource_id']!==(int)$w['resource_id']||((string)$row['status']!=='Under Repair'||!in_array($row['condition_status'],['Damaged','Missing Parts','Needs Repair'],true)))throw new DomainException("The linked unit is not in a repairable state.");$pdo->prepare("UPDATE equipment_units SET status='Available',condition_status='Good',updated_at=NOW() WHERE unit_id=? AND status='Under Repair'")->execute([$unitId]);gsoRecalculateSerializedStock($pdo,(int)$w['resource_id']);$restored=1;
  }elseif((int)$w['quantity']>0){$restored=restoreRepairedStock($pdo,(int)$w['resource_id'],(int)$w['quantity']);if($restored!==(int)$w['quantity'])throw new DomainException("The aggregate repair quantity no longer matches inventory state.");}
  $q=$pdo->prepare("UPDATE maintenance_schedules SET status='Completed',completion_notes=?,completed_at=NOW(),restored_at=NOW(),updated_by=?,updated_at=NOW() WHERE maintenance_id=? AND status IN ('Scheduled','In Progress') AND restored_at IS NULL");$q->execute([$notes?:null,$actorId,$maintenanceId]);if($q->rowCount()!==1)throw new DomainException("This work order was already updated.");refreshResourceOperationalStatus($pdo,(int)$w['resource_id']);$pdo->commit();return ['ok'=>true,'message'=>"Work order completed; {$restored} unit(s) restored.",'restored'=>$restored];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}
}

function gsoRecordBorrowerAccountability(PDO $pdo,int $returnItemId,int $actorId,string $status,string $notes):array{
 if(!in_array($status,['Pending Review','Confirmed','Waived','Resolved'],true))return ['ok'=>false,'message'=>'Invalid accountability status.'];
 try{$pdo->beginTransaction();$u=$pdo->prepare("SELECT 1 FROM users WHERE user_id=? AND role IN ('Admin','GSO Staff') AND account_status='Approved' AND email_verified=1 FOR UPDATE");$u->execute([$actorId]);if(!$u->fetchColumn())throw new DomainException("Not authorized.");$s=$pdo->prepare("SELECT i.return_item_id,i.unit_id,i.inspection_condition,rs.request_id,rr.borrower_id FROM return_submission_items i JOIN return_submissions rs ON rs.return_id=i.return_id JOIN resource_requests rr ON rr.request_id=rs.request_id WHERE i.return_item_id=? FOR UPDATE");$s->execute([$returnItemId]);$d=$s->fetch(PDO::FETCH_ASSOC);if(!$d||!in_array((string)$d['inspection_condition'],['Damaged','Needs Repair','Missing Parts','Lost'],true))throw new DomainException("This return detail is not eligible for accountability review.");$type=match((string)$d['inspection_condition']){'Lost'=>'Loss','Missing Parts'=>'Missing Parts',default=>'Damage'};$sql="INSERT INTO borrower_liabilities(request_id,return_item_id,borrower_id,equipment_unit_id,accountability_type,accountability_status,reviewed_by,reviewed_at,resolution_notes) VALUES(?,?,?,?,?,?,?,NOW(),?) ON DUPLICATE KEY UPDATE accountability_status=VALUES(accountability_status),reviewed_by=VALUES(reviewed_by),reviewed_at=NOW(),resolution_notes=VALUES(resolution_notes)";$pdo->prepare($sql)->execute([(int)$d['request_id'],$returnItemId,$d['borrower_id']===null?null:(int)$d['borrower_id'],((int)$d['unit_id'])?:null,$type,$status,$actorId,$notes?:null]);$pdo->commit();return ['ok'=>true,'message'=>'Accountability review recorded.'];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}
}

/** Validate the exact repair source before assignment or restoration. */
function gsoValidateRepairSource(PDO $pdo,int $id): void
{
    $s=$pdo->prepare('SELECT * FROM maintenance_schedules WHERE maintenance_id=? FOR UPDATE');$s->execute([$id]);$w=$s->fetch(PDO::FETCH_ASSOC);if(!$w)throw new DomainException('Work order not found.');
    $s=$pdo->prepare('SELECT condition_status FROM resources WHERE resource_id=? FOR UPDATE');$s->execute([$w['resource_id']]);if($s->fetchColumn()==='Lost')throw new DomainException('Lost resources cannot be restored through maintenance.');
    if($w['source_return_item_id']!==null){
        $s=$pdo->prepare('SELECT d.*,l.resource_id,l.line_kind FROM return_submission_items d JOIN request_items l ON l.request_item_id=d.request_item_id WHERE d.return_item_id=? FOR UPDATE');$s->execute([$w['source_return_item_id']]);$source=$s->fetch(PDO::FETCH_ASSOC);
        if(!$source||(int)$source['stock_applied']!==1||(int)$source['lost_quantity']!==0||(int)$source['returned_quantity']<1||!in_array($source['inspection_condition'],['Damaged','Missing Parts','Needs Repair'],true)||(int)$source['resource_id']!==(int)$w['resource_id']||($source['unit_id']===null?$w['equipment_unit_id']!==null:(int)$source['unit_id']!==(int)$w['equipment_unit_id']))throw new DomainException('Only the matching repairable return target may enter maintenance. Lost is not repairable.');
        if($source['line_kind']!=='Facility'&&((int)$w['quantity']<1||(int)$w['quantity']>(int)$source['returned_quantity']))throw new DomainException('Repair quantity exceeds the inspected repairable quantity.');
        $s=$pdo->prepare('SELECT COUNT(*) n,COALESCE(SUM(quantity),0) qty FROM maintenance_schedules WHERE source_return_item_id=? AND maintenance_id<>? AND restored_at IS NOT NULL');$s->execute([$w['source_return_item_id'],$id]);$done=$s->fetch(PDO::FETCH_ASSOC);
        if(($source['line_kind']==='Facility'&&(int)$done['n']>0)||(int)$done['qty']+(int)$w['quantity']>(int)$source['returned_quantity'])throw new DomainException('This return target has already been restored.');
    }
    if($w['equipment_unit_id']!==null){$s=$pdo->prepare('SELECT status,condition_status,resource_id FROM equipment_units WHERE unit_id=? FOR UPDATE');$s->execute([$w['equipment_unit_id']]);$unit=$s->fetch(PDO::FETCH_ASSOC);if(!$unit||(int)$unit['resource_id']!==(int)$w['resource_id']||$unit['status']==='Lost'||$unit['condition_status']==='Lost')throw new DomainException('Lost units cannot be assigned or restored through maintenance.');}
}
